// Prove the minimal-call correction flow for the 4 ledger errors
// Target: 6 API calls total (1 discover + 1 account lookup + 1 reverse + 3 correction vouchers)
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa(`0:${TOKEN}`);
let callCount = 0;

async function api(method: string, path: string, body?: any) {
  callCount++;
  const url = `${BASE}${path}`;
  const opts: RequestInit = {
    method,
    headers: { "Authorization": AUTH, "Content-Type": "application/json" },
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(url, opts);
  const text = await res.text();
  let json: any;
  try { json = JSON.parse(text); } catch { json = text; }
  console.log(`[Call ${callCount}] ${method} ${path.substring(0, 80)} → ${res.status}`);
  if (!res.ok) { console.error(JSON.stringify(json, null, 2)); throw new Error(`${res.status}`); }
  if (json.values !== undefined) return json.values;
  if (json.value !== undefined) return json.value;
  return json;
}

// ============ CALL 1: Discover all vouchers for Jan-Feb 2026 ============
const vouchers: any[] = await api("GET",
  "/ledger/voucher?dateFrom=2026-01-01&dateTo=2026-03-01&fields=*,postings(*,account(*),vatType(*))&count=1000"
);
console.log(`\nFound ${vouchers.length} vouchers`);

// Build account cache from existing voucher postings
const accountCache = new Map<number, { id: number; number: number; name: string }>();
for (const v of vouchers) {
  for (const p of (v.postings ?? [])) {
    if (p.account?.number && p.account?.id) {
      accountCache.set(p.account.number, { id: p.account.id, number: p.account.number, name: p.account.name });
    }
  }
}
console.log(`Account cache: ${[...accountCache.keys()].sort((a, b) => a - b).join(', ')}`);

// ============ Identify the 4 errors ============

// Error 1: Wrong account 7300, amount 1650
let error1Voucher: any = null;
for (const v of vouchers) {
  for (const p of (v.postings ?? [])) {
    if (p.account?.number === 7300 && Math.abs(p.amountGross) === 1650) {
      error1Voucher = v;
      break;
    }
  }
}
console.log(`\nError 1 (wrong account 7300→7000, 1650): voucher ${error1Voucher?.id}, date ${error1Voucher?.date}`);
for (const p of (error1Voucher?.postings ?? [])) {
  console.log(`  ${p.account?.number}: gross=${p.amountGross}`);
}

// Error 2: Duplicate voucher, account 6500, amount 3100
const dupVouchers: any[] = [];
for (const v of vouchers) {
  for (const p of (v.postings ?? [])) {
    if (p.account?.number === 6500 && Math.abs(p.amountGross) === 3100) {
      dupVouchers.push(v);
      break;
    }
  }
}
// The duplicate is the one with later ID or with "duplikat" in description
const duplicateVoucher = dupVouchers.find((v: any) => v.description?.toLowerCase().includes('duplikat'))
  ?? dupVouchers[dupVouchers.length - 1];
console.log(`\nError 2 (duplicate 6500, 3100): ${dupVouchers.length} matching vouchers`);
console.log(`  Duplicate to reverse: voucher ${duplicateVoucher?.id} "${duplicateVoucher?.description}"`);

// Error 3: Missing VAT line, account 6540, amount 20950 excl
let error3Voucher: any = null;
for (const v of vouchers) {
  const has6540 = (v.postings ?? []).some((p: any) => p.account?.number === 6540);
  const has2710 = (v.postings ?? []).some((p: any) => p.account?.number === 2710);
  if (has6540 && !has2710) {
    for (const p of (v.postings ?? [])) {
      if (p.account?.number === 6540 && (Math.abs(p.amountGross) === 20950 || Math.abs(p.amount) === 20950)) {
        error3Voucher = v;
        break;
      }
    }
  }
}
console.log(`\nError 3 (missing VAT, 6540, 20950): voucher ${error3Voucher?.id}, date ${error3Voucher?.date}`);
for (const p of (error3Voucher?.postings ?? [])) {
  console.log(`  ${p.account?.number} (id=${p.account?.id}): gross=${p.amountGross}, net=${p.amount}`);
}
// Find the contra account from error 3
const error3ContraPosting = (error3Voucher?.postings ?? []).find((p: any) =>
  p.account?.number !== 6540 && p.amountGross < 0
);
console.log(`  Contra account: ${error3ContraPosting?.account?.number} id=${error3ContraPosting?.account?.id}`);

// Error 4: Incorrect amount, account 6340, 18100 instead of 6050
let error4Voucher: any = null;
for (const v of vouchers) {
  for (const p of (v.postings ?? [])) {
    if (p.account?.number === 6340 && (Math.abs(p.amountGross) === 18100 || Math.abs(p.amount) === 18100)) {
      error4Voucher = v;
      break;
    }
  }
}
console.log(`\nError 4 (incorrect amount, 6340, 18100→6050): voucher ${error4Voucher?.id}, date ${error4Voucher?.date}`);
for (const p of (error4Voucher?.postings ?? [])) {
  console.log(`  ${p.account?.number} (id=${p.account?.id}): gross=${p.amountGross}`);
}
// Find the contra account from error 4
const error4ContraPosting = (error4Voucher?.postings ?? []).find((p: any) =>
  p.account?.number !== 6340 && p.amountGross < 0
);
console.log(`  Contra account: ${error4ContraPosting?.account?.number} id=${error4ContraPosting?.account?.id}`);

// ============ CALL 2: Get accounts not in cache (7000, 2710) ============
const neededAccounts: number[] = [];
if (!accountCache.has(7000)) neededAccounts.push(7000);
if (!accountCache.has(2710)) neededAccounts.push(2710);
console.log(`\nMissing accounts to fetch: ${neededAccounts.join(', ')}`);

if (neededAccounts.length > 0) {
  const fetched: any[] = await api("GET", `/ledger/account?number=${neededAccounts.join(',')}&fields=*`);
  for (const a of fetched) {
    accountCache.set(a.number, { id: a.id, number: a.number, name: a.name });
    console.log(`  Fetched account ${a.number}: id=${a.id} "${a.name}"`);
  }
}

const getAcct = (num: number) => accountCache.get(num)!;

// ============ CALL 3: Reverse the duplicate voucher ============
console.log(`\n--- Reversing duplicate voucher ${duplicateVoucher.id} ---`);
const reversed = await api("PUT", `/ledger/voucher/${duplicateVoucher.id}/:reverse?date=2026-03-21`);
console.log(`  Reversed → new voucher ${reversed?.id}`);

// ============ CALL 4: Correction for wrong account (7300→7000, 1650) ============
console.log(`\n--- Correction 1: Wrong account 7300→7000, 1650 ---`);
const corr1 = await api("POST", "/ledger/voucher?sendToLedger=true", {
  date: "2026-03-21",
  description: "Korreksjon: Telefonkostnad feil konto 7300→7000",
  postings: [
    { account: { id: getAcct(7000).id }, amountGross: 1650, amountGrossCurrency: 1650, row: 1 },
    { account: { id: getAcct(7300).id }, amountGross: -1650, amountGrossCurrency: -1650, row: 2 },
  ]
});
console.log(`  Created correction voucher ${corr1?.id}`);

// ============ CALL 5: Correction for missing VAT (6540 20950 excl → add 2710) ============
// VAT amount = 20950 * 0.25 = 5237.50
const vatAmount = 20950 * 0.25;
console.log(`\n--- Correction 3: Missing VAT line, debit 2710 ${vatAmount} ---`);
const corr3 = await api("POST", "/ledger/voucher?sendToLedger=true", {
  date: "2026-03-21",
  description: "Korreksjon: Manglende MVA på varekjøp",
  postings: [
    { account: { id: getAcct(2710).id }, amountGross: vatAmount, amountGrossCurrency: vatAmount, row: 1 },
    { account: { id: error3ContraPosting.account.id }, amountGross: -vatAmount, amountGrossCurrency: -vatAmount, row: 2 },
  ]
});
console.log(`  Created correction voucher ${corr3?.id}`);

// ============ CALL 6: Correction for incorrect amount (6340: 18100→6050, diff=12050) ============
const diff = 18100 - 6050; // 12050
console.log(`\n--- Correction 4: Incorrect amount, credit 6340 ${diff} ---`);
const corr4 = await api("POST", "/ledger/voucher?sendToLedger=true", {
  date: "2026-03-21",
  description: "Korreksjon: Husleie feil beløp 18100→6050",
  postings: [
    { account: { id: getAcct(6340).id }, amountGross: -diff, amountGrossCurrency: -diff, row: 1 },
    { account: { id: error4ContraPosting.account.id }, amountGross: diff, amountGrossCurrency: diff, row: 2 },
  ]
});
console.log(`  Created correction voucher ${corr4?.id}`);

console.log(`\n=== DONE in ${callCount} API calls ===`);

